  function getCurrentGameObject() {
    const g = state.currentGrade;
    const subjects = GRADE_SUBJECTS_CONFIG[g] || GRADE_SUBJECTS_CONFIG[1];
    if (subjects) {
      for (const s of subjects) {
        if (s.games) {
          const gm = s.games.find(x => x.id === state.currentGameType);
          if (gm) return gm;
        }
      }
    }
    return null;
  }

