  function openArcadeHub() {
    lockInteractions(300);
    state.currentSection = 'arcade';
    if (DOM.btnNavHome) DOM.btnNavHome.classList.remove('active');
    DOM.gradeChips.forEach(chip => chip.classList.remove('active'));
    
    function handleSidebarEnglishClick(e) {
      if (e && e.preventDefault) e.preventDefault();
      audio.playClick();
      if (typeof closeMobileSidebar === 'function') closeMobileSidebar();
      const modalSelectGrade = document.getElementById('modalSelectGrade');
      if (modalSelectGrade) closeModal(modalSelectGrade);

      // İngilizce dersini aç: Eğer aktif sınıf 2, 3 veya 4 ise koru, yoksa varsayılan 2. sınıfı aç
      const curG = state.currentGrade;
      const targetGrade = (curG >= 2 && curG <= 4) ? curG : 2;
      setGrade(targetGrade);
      if (typeof selectSubject === 'function') {
        selectSubject('english');
      }

      // Sidebar çip aktifliğini İngilizce'ye ver
      if (DOM.btnNavHome) DOM.btnNavHome.classList.remove('active');
      if (DOM.gradeChips) DOM.gradeChips.forEach(c => c.classList.remove('active'));
      const btnSidebarEnglish = document.getElementById('btnSidebarEnglish');
      if (btnSidebarEnglish) btnSidebarEnglish.classList.add('active');
      const btnSidebarDuels = document.getElementById('btnSidebarDuels');
      if (btnSidebarDuels) btnSidebarDuels.classList.remove('active');

      try {
        if (window.location.hash !== '#ingilizce') {
          history.pushState({ route: 'ingilizce' }, '', '#ingilizce');
        }
      } catch (err) {}
    }

    const btnSidebarEnglish = document.getElementById('btnSidebarEnglish');
    if (btnSidebarEnglish) {
      addTapListener(btnSidebarEnglish, openEnglishModule);
    }

    const btnSidebarDuels = document.getElementById('btnSidebarDuels');
    if (btnSidebarDuels) btnSidebarDuels.classList.add('active');

    if (DOM.maarifReadingContainer) DOM.maarifReadingContainer.classList.add('hide');
    if (DOM.homeShowcaseSection) DOM.homeShowcaseSection.classList.add('hide');
    if (DOM.subjectsSection) DOM.subjectsSection.classList.add('hide');
    if (DOM.gamesSection) DOM.gamesSection.classList.add('hide');

    const arcadeSec = document.getElementById('arcadeHubSection');
    const cardsView = document.getElementById('arcadeCardsView');
    const stageView = document.getElementById('arcadeStageView');
    if (arcadeSec) arcadeSec.classList.remove('hide');
    if (cardsView) cardsView.classList.remove('hide');
    if (stageView) stageView.classList.add('hide');
    ArcadeHub.activeGame = null;
  }
  window.openArcadeHub = openArcadeHub;

  function closeArcadeStageToCards() {
    audio.playClick();
    const oldModal = document.getElementById('arcadeVictoryModal');
    if (oldModal) oldModal.remove();
    const cardsView = document.getElementById('arcadeCardsView');
    const stageView = document.getElementById('arcadeStageView');
    if (cardsView) cardsView.classList.remove('hide');
    if (stageView) stageView.classList.add('hide');
    ArcadeHub.activeGame = null;
  }

  function showArcadeVictoryModal({ title, subtitle = '', badgeText = 'ŞAMPİYON', icon = '🏆', onRestart }) {
    audio.playFanfare();
    if (typeof launchConfetti === 'function') {
      launchConfetti();
      setTimeout(launchConfetti, 450);
    }
    const oldModal = document.getElementById('arcadeVictoryModal');
    if (oldModal) oldModal.remove();

    const overlay = document.createElement('div');
    overlay.id = 'arcadeVictoryModal';
    overlay.className = 'arcade-victory-overlay';
    overlay.innerHTML = `
      <div class="arcade-victory-dialog">
        <div class="vic-rays"></div>
        <div class="vic-icon-ring">
          <span class="vic-icon">${icon}</span>
          <span class="vic-sparkle s1">✨</span>
          <span class="vic-sparkle s2">⭐</span>
          <span class="vic-sparkle s3">🌟</span>
        </div>
        <div class="vic-badge">${badgeText}</div>
        <h2 class="vic-title">${title}</h2>
        <p class="vic-sub">${subtitle}</p>
        <div class="vic-actions">
          <button class="vic-btn vic-btn-restart" id="btnVicRestart" type="button">
            <span>🔄</span> Tekrar Oyna
          </button>
          <button class="vic-btn vic-btn-hub" id="btnVicHub" type="button">
            <span>🏠</span> Oyun Merkezine Dön
          </button>
        </div>
      </div>
    `;

    document.body.appendChild(overlay);

    const bRestart = overlay.querySelector('#btnVicRestart');
    if (bRestart) {
      addTapListener(bRestart, () => {
        audio.playClick();
        overlay.classList.add('closing');
        setTimeout(() => overlay.remove(), 240);
        if (typeof onRestart === 'function') onRestart();
      });
    }

    const bHub = overlay.querySelector('#btnVicHub');
    if (bHub) {
      addTapListener(bHub, () => {
        audio.playClick();
        overlay.classList.add('closing');
        setTimeout(() => overlay.remove(), 240);
        closeArcadeStageToCards();
      });
    }
  }

  function launchArcadeGame(gameId) {
    audio.playClick();
    ArcadeHub.activeGame = gameId;
    const cardsView = document.getElementById('arcadeCardsView');
    const stageView = document.getElementById('arcadeStageView');
    if (cardsView) cardsView.classList.add('hide');
    if (stageView) stageView.classList.remove('hide');

    if (gameId === 'tug') initArcadeTugGame();
    else if (gameId === 'sudoku') initArcadeSudokuGame();
    else if (gameId === 'xox') initArcadeXoxGame();
    else if (gameId === 'memory') initArcadeMemoryGame();
    else if (gameId === 'flower') initArcadeFlowerGame();
    else if (gameId === 'buzzer') initArcadeBuzzerGame();
  }

  // =========================================================================
  // OYUN 1: ⚔️ ÇARPMA SAVAŞI (HALAT ÇEKME DÜELLOSU - 2 KİŞİLİK)
  // =========================================================================
  function generateTugQuestion(diff) {
    let a, b, op = '×', ans;
    if (diff === 'easy') {
      a = Math.floor(Math.random() * 5) + 1;
      b = Math.floor(Math.random() * 9) + 1;
      ans = a * b;
    } else if (diff === 'medium') {
      a = Math.floor(Math.random() * 4) + 6; // 6..9
      b = Math.floor(Math.random() * 8) + 2; // 2..9
      ans = a * b;
    } else if (diff === 'hard') {
      a = Math.floor(Math.random() * 9) + 2; // 2..10
      b = Math.floor(Math.random() * 9) + 2; // 2..10
      ans = a * b;
    } else {
      // 4 İşlem Karma
      const ops = ['+', '-', '×', '÷'];
      op = ops[Math.floor(Math.random() * ops.length)];
      if (op === '+') {
        a = Math.floor(Math.random() * 40) + 10;
        b = Math.floor(Math.random() * 40) + 10;
        ans = a + b;
      } else if (op === '-') {
        a = Math.floor(Math.random() * 50) + 25;
        b = Math.floor(Math.random() * 22) + 5;
        ans = a - b;
      } else if (op === '×') {
        a = Math.floor(Math.random() * 8) + 2;
        b = Math.floor(Math.random() * 8) + 2;
        ans = a * b;
      } else {
        b = Math.floor(Math.random() * 8) + 2;
        ans = Math.floor(Math.random() * 9) + 2;
        a = b * ans;
      }
    }

    const optsSet = new Set([ans]);
    while (optsSet.size < 3) {
      const delta = (Math.floor(Math.random() * 5) + 1) * (Math.random() < 0.5 ? 1 : -1);
      const cand = Math.max(1, ans + delta);
      if (cand !== ans) optsSet.add(cand);
    }
    const opts = Array.from(optsSet).sort(() => Math.random() - 0.5);
    return {
      text: `${a} ${op} ${b} = ?`,
      answer: ans,
      options: opts
    };
  }

  function initArcadeTugGame() {
    const iconEl = document.getElementById('arcadeStageIcon');
    const titleEl = document.getElementById('arcadeStageTitle');
    const toolbarEl = document.getElementById('arcadeStageToolbar');
    if (iconEl) iconEl.textContent = '⚔️';
    if (titleEl) titleEl.textContent = 'Çarpma Savaşı: Halat Çekme Düellosu';

    const t = ArcadeHub.tug;
    t.ropePos = 0;
    t.p1Locked = false;
    t.p2Locked = false;
    t.p1Streak = 0;
    t.p2Streak = 0;
    t.lastPullText = '';
    t.lastPullSide = null;
    t.isOver = false;
    t.currentQ = generateTugQuestion(t.diff);

    if (toolbarEl) {
      toolbarEl.innerHTML = `
        <div class="arc-toolbar-group">
          <button class="arc-pill-btn ${t.diff === 'easy' ? 'active' : ''}" data-tug-diff="easy" type="button">Kolay (1-5'ler)</button>
          <button class="arc-pill-btn ${t.diff === 'medium' ? 'active' : ''}" data-tug-diff="medium" type="button">Orta (6-9'lar)</button>
          <button class="arc-pill-btn ${t.diff === 'hard' ? 'active' : ''}" data-tug-diff="hard" type="button">Zor (Tüm Tablo)</button>
          <button class="arc-pill-btn ${t.diff === 'mixed' ? 'active' : ''}" data-tug-diff="mixed" type="button">4 İşlem Karma</button>
          <button class="arc-pill-btn arc-btn-restart" id="btnTugRestart" type="button">🔄 Yeni Maç</button>
        </div>
      `;
      toolbarEl.querySelectorAll('[data-tug-diff]').forEach(btn => {
        addTapListener(btn, () => {
          ArcadeHub.tug.diff = btn.getAttribute('data-tug-diff');
          audio.playClick();
          initArcadeTugGame();
        });
      });
      const btnRestart = document.getElementById('btnTugRestart');
      if (btnRestart) addTapListener(btnRestart, () => { audio.playClick(); initArcadeTugGame(); });
    }

    renderArcadeTugStage();
  }

  function renderArcadeTugStage() {
    const canvas = document.getElementById('arcadeStageCanvas');
    if (!canvas) return;
    const t = ArcadeHub.tug;
    const q = t.currentQ;
    // ropePos: -5 (Blue wins on left) .. 0 (Center) .. +5 (Orange wins on right)
    const pct = 50 + (t.ropePos * 8.6);
    const blueSteps = Math.max(0, -Math.floor(t.ropePos));
    const orangeSteps = Math.max(0, Math.floor(t.ropePos));

    let stepsHtml = '';
    for (let i = -5; i <= 5; i++) {
      const isBlue = i < 0;
      const isOrange = i > 0;
      const isCenter = i === 0;
      let activeCls = '';
      if (isBlue && t.ropePos <= i) activeCls = 'filled-blue';
      else if (isOrange && t.ropePos >= i) activeCls = 'filled-orange';
      else if (isCenter && Math.abs(t.ropePos) < 0.5) activeCls = 'active-center';

      stepsHtml += `
        <div class="ruler-step-tick ${isBlue ? 'tick-blue' : (isOrange ? 'tick-orange' : 'tick-center')} ${activeCls}">
          <span class="tick-num">${i === 0 ? '0' : Math.abs(i)}</span>
          <span class="tick-dot"></span>
        </div>
      `;
    }

    canvas.innerHTML = `
      <div class="arc-tug-arena">
        <!-- Üst Halat Çekme Sahnesi & Durum Çubuğu -->
        <div class="tug-top-scoreboard">
          <div class="tug-team-pill team-blue">
            <span class="team-dot">🔵</span>
            <span class="team-name">1. Oyuncu (Mavi)</span>
            <span class="team-wins">Zafer: <strong>${t.p1Score}</strong></span>
          </div>

          <div class="tug-match-info">
            <span class="tug-info-badge">
              ${t.isOver
                ? (t.ropePos <= -5 ? '🏆 MAVİ TAKIM HALATI ÇEKTİ VE KAZANDI! 🎉' : '🏆 TURUNCU TAKIM HALATI ÇEKTİ VE KAZANDI! 🎉')
                : (t.p1Streak >= 3 ? '🔥 MAVİ TAKIM ALEV ALDI (Combo x2)!' : (t.p2Streak >= 3 ? '🔥 TURUNCU TAKIM ALEV ALDI (Combo x2)!' : '🪢 Doğru cevaba ilk basan halatı 1 adım çeker!'))}
            </span>
          </div>

          <div class="tug-team-pill team-orange">
            <span class="team-dot">🟠</span>
            <span class="team-name">2. Oyuncu (Turuncu)</span>
            <span class="team-wins">Zafer: <strong>${t.p2Score}</strong></span>
          </div>
        </div>

        <!-- Gerçek Halat Çekme Sahnesi (3D Maskotlar, Halat ve Düğüm) -->
        <div class="tug-stage-canvas-wrap">
          <div class="tug-rope-scene-header">
            <div class="tug-zone-target zone-left">⬅️ MAVİ HEDEF (+5)</div>
            <div class="tug-center-pin">📍 ORTA ÇİZGİ</div>
            <div class="tug-zone-target zone-right">TURUNCU HEDEF (+5) ➡️</div>
          </div>

          <div class="tug-rope-arena-field">
            <!-- Sol Çekici (Mavi Maskot) -->
            <div class="tug-puller puller-blue ${t.ropePos < 0 ? 'pulling-hard' : ''}">
              <div class="puller-avatar-box">
                <span class="puller-emoji">🤖</span>
                <span class="puller-flag">🔵</span>
              </div>
              <div class="puller-hands-rope"></div>
              <span class="puller-score-tag">${blueSteps} / 5</span>
            </div>

            <!-- Kalın Dokulu Halat ve Hareketli Düğüm -->
            <div class="tug-braided-rope-body">
              <div class="tug-rope-texture-strip"></div>
              
              <!-- Orta Düğüm ve Moli Hakem -->
              <div class="tug-knot-carrier ${t.lastPullSide ? 'pull-active-' + t.lastPullSide : ''}" style="left: ${pct}%;">
                <div class="tug-knot-ribbon">🎀</div>
                <div class="tug-knot-referee">
                  <img src="assets/mascot/moli.webp" alt="Hakem Moli" class="referee-moli-img" width="52" height="52">
                </div>
                <div class="tug-knot-needle"></div>
                ${t.lastPullText ? `<div class="tug-floating-bubble float-${t.lastPullSide}">${t.lastPullText}</div>` : ''}
              </div>
            </div>

            <!-- Sağ Çekici (Turuncu Maskot) -->
            <div class="tug-puller puller-orange ${t.ropePos > 0 ? 'pulling-hard' : ''}">
              <div class="puller-hands-rope"></div>
              <div class="puller-avatar-box">
                <span class="puller-emoji">🦊</span>
                <span class="puller-flag">🟠</span>
              </div>
              <span class="puller-score-tag">${orangeSteps} / 5</span>
            </div>
          </div>

          <!-- Adım İşaretçileri Cetveli (-5 .. 0 .. +5) -->
          <div class="tug-ruler-track">
            ${stepsHtml}
          </div>
        </div>

        <!-- İkiye Bölünmüş 3D Dokunsal Oyuncu Panelleri -->
        <div class="tug-split-players">
          <!-- Sol: 1. Oyuncu (Mavi Köşe) -->
          <div class="tug-player-card player-blue ${t.p1Locked ? 'is-locked' : ''} ${t.p1Streak >= 3 ? 'is-on-fire' : ''}" id="tugP1Card">
            <div class="tug-card-top-bar">
              <div class="player-corner-title">
                <span class="corner-dot">🔵</span>
                <span>1. Oyuncu (Mavi Köşe)</span>
              </div>
              ${t.p1Streak >= 3 ? '<div class="fire-combo-badge">🔥 ALEV ALDI (Combo x2)</div>' : (t.p1Streak > 1 ? `<div class="streak-badge">⭐ ${t.p1Streak}x Seri</div>` : '')}
            </div>

            <div class="tug-question-box">
              <span class="q-label">Hemen Çöz:</span>
              <span class="q-math-text">${q.text}</span>
            </div>

            <div class="tug-options-row">
              ${q.options.map((opt) => `
                <button class="tug-opt-btn btn-blue" data-tug-p="1" data-tug-val="${opt}" type="button" ${t.isOver ? 'disabled' : ''}>
                  <span class="btn-opt-num">${opt}</span>
                </button>
              `).join('')}
            </div>
            <div class="tug-lock-msg">🔒 Yanlış cevap! 1.2 sn kilitlendi...</div>
          </div>

          <!-- Sağ: 2. Oyuncu (Turuncu Köşe) -->
          <div class="tug-player-card player-orange ${t.p2Locked ? 'is-locked' : ''} ${t.p2Streak >= 3 ? 'is-on-fire' : ''}" id="tugP2Card">
            <div class="tug-card-top-bar">
              <div class="player-corner-title">
                <span class="corner-dot">🟠</span>
                <span>2. Oyuncu (Turuncu Köşe)</span>
              </div>
              ${t.p2Streak >= 3 ? '<div class="fire-combo-badge">🔥 ALEV ALDI (Combo x2)</div>' : (t.p2Streak > 1 ? `<div class="streak-badge">⭐ ${t.p2Streak}x Seri</div>` : '')}
            </div>

            <div class="tug-question-box">
              <span class="q-label">Hemen Çöz:</span>
              <span class="q-math-text">${q.text}</span>
            </div>

            <div class="tug-options-row">
              ${q.options.map((opt) => `
                <button class="tug-opt-btn btn-orange" data-tug-p="2" data-tug-val="${opt}" type="button" ${t.isOver ? 'disabled' : ''}>
                  <span class="btn-opt-num">${opt}</span>
                </button>
              `).join('')}
            </div>
            <div class="tug-lock-msg">🔒 Yanlış cevap! 1.2 sn kilitlendi...</div>
          </div>
        </div>
      </div>
    `;

    canvas.querySelectorAll('[data-tug-p]').forEach(btn => {
      btn.addEventListener('pointerdown', (e) => {
        if (e.cancelable) e.preventDefault();
        const p = parseInt(btn.getAttribute('data-tug-p'), 10);
        const val = parseInt(btn.getAttribute('data-tug-val'), 10);
        handleTugAnswer(p, val);
      });
    });
  }

  function handleTugAnswer(playerNum, val) {
    const t = ArcadeHub.tug;
    if (t.isOver) return;
    if (playerNum === 1 && t.p1Locked) return;
    if (playerNum === 2 && t.p2Locked) return;

    if (val === t.currentQ.answer) {
      audio.playCorrect();
      audio.playPop();

      let pullDist = 1;
      if (playerNum === 1) {
        t.p1Streak += 1;
        t.p2Streak = 0;
        if (t.p1Streak >= 3) {
          pullDist = 1.5;
          t.lastPullText = '🔥 ALEV ALDI! COMBO x2! (+1.5 Çekiş)';
        } else {
          t.lastPullText = '+1 ÇEKİŞ! 💪';
        }
        t.lastPullSide = 'blue';
        t.ropePos -= pullDist;
      } else {
        t.p2Streak += 1;
        t.p1Streak = 0;
        if (t.p2Streak >= 3) {
          pullDist = 1.5;
          t.lastPullText = '🔥 ALEV ALDI! COMBO x2! (+1.5 Çekiş)';
        } else {
          t.lastPullText = '+1 ÇEKİŞ! 💪';
        }
        t.lastPullSide = 'orange';
        t.ropePos += pullDist;
      }

      t.ropePos = Math.max(-5, Math.min(5, t.ropePos));
      t.p1Locked = false;
      t.p2Locked = false;

      if (t.ropePos <= -5 || t.ropePos >= 5) {
        t.isOver = true;
        if (t.ropePos <= -5) t.p1Score += 1;
        else t.p2Score += 1;
        renderArcadeTugStage();
        audio.playFanfare();
        if (typeof launchConfetti === 'function') launchConfetti();
        if (!state.isMuted && state.soundEnabled) {
          const winnerText = t.ropePos <= -5 ? 'Tebrikler! 1. Oyuncu Mavi Takım halatı çekti ve kazandı!' : 'Tebrikler! 2. Oyuncu Turuncu Takım halatı çekti ve kazandı!';
          audio.speakTurkishText(winnerText);
        }
        const winnerTitle = t.ropePos <= -5 ? '1. OYUNCU (MAVİ) KAZANDI! 🏆' : '2. OYUNCU (TURUNCU) KAZANDI! 🏆';
        showArcadeVictoryModal({
          title: winnerTitle,
          subtitle: 'Çarpma düellosunda halatı kendi tarafına çekerek şampiyon oldun!',
          badgeText: 'HALAT ŞAMPİYONU',
          icon: '⚔️',
          onRestart: () => initArcadeTugGame()
        });
      } else {
        t.currentQ = generateTugQuestion(t.diff);
        renderArcadeTugStage();
      }
    } else {
      audio.playWrong();
      if (typeof audio.playIceFreeze === 'function') audio.playIceFreeze();
      if (playerNum === 1) {
        t.p1Streak = 0;
        t.p1Locked = true;
        const c1 = document.getElementById('tugP1Card');
        if (c1) c1.classList.add('is-locked');
        setTimeout(() => {
          t.p1Locked = false;
          const el = document.getElementById('tugP1Card');
          if (el) el.classList.remove('is-locked');
        }, 1200);
      } else {
        t.p2Streak = 0;
        t.p2Locked = true;
        const c2 = document.getElementById('tugP2Card');
        if (c2) c2.classList.add('is-locked');
        setTimeout(() => {
          t.p2Locked = false;
          const el = document.getElementById('tugP2Card');
          if (el) el.classList.remove('is-locked');
        }, 1200);
      }
    }
  }

  // =========================================================================
  // OYUN 2: 🧩 ÇOCUK SUDOKUSU (MANTIK VE ZEKA ATÖLYESİ)
  // =========================================================================
  const SUDOKU_ITEMS_MAP = {
    // 3D Canlı Meyveler
    '🍎': { type: 'img', src: 'assets/icons/3d/apple.webp', alt: 'Elma', name: 'Elma' },
    '🍌': { type: 'img', src: 'assets/icons/3d/banana.webp', alt: 'Muz', name: 'Muz' },
    '🍓': { type: 'img', src: 'assets/icons/3d/strawberry.webp', alt: 'Çilek', name: 'Çilek' },
    '🍇': { type: 'img', src: 'assets/icons/3d/grapes.webp', alt: 'Üzüm', name: 'Üzüm' },

    // 3D Şekil & Uzay
    '⭐': { type: 'img', src: 'assets/icons/3d/star.webp', alt: 'Yıldız', name: 'Yıldız' },
    '💎': { type: 'img', src: 'assets/icons/3d/gem.webp', alt: 'Elmas', name: 'Elmas' },
    '🔷': { type: 'img', src: 'assets/icons/3d/gem.webp', alt: 'Elmas', name: 'Elmas' },
    '❤️': { type: 'img', src: 'assets/icons/3d/heart.webp', alt: 'Kalp', name: 'Kalp' },
    '🟢': { type: 'img', src: 'assets/icons/3d/heart.webp', alt: 'Kalp', name: 'Kalp' },
    '🚀': { type: 'img', src: 'assets/icons/3d/rocket.webp', alt: 'Roket', name: 'Roket' },
    '🔺': { type: 'img', src: 'assets/icons/3d/rocket.webp', alt: 'Roket', name: 'Roket' },

    // Canlı 3D Rakam Rozetleri (1 - 6)
    '1': { type: 'num', num: '1', cls: 'sdk-n1', name: '1' },
    '2': { type: 'num', num: '2', cls: 'sdk-n2', name: '2' },
    '3': { type: 'num', num: '3', cls: 'sdk-n3', name: '3' },
    '4': { type: 'num', num: '4', cls: 'sdk-n4', name: '4' },
    '5': { type: 'num', num: '5', cls: 'sdk-n5', name: '5' },
    '6': { type: 'num', num: '6', cls: 'sdk-n6', name: '6' }
  };

  function renderSudokuSymbolHtml(val, isKeypad = false) {
    if (!val) return '';
    const item = SUDOKU_ITEMS_MAP[val];
    if (!item) {
      return `<span class="sdk-raw-sym">${val}</span>`;
    }
    if (item.type === 'img') {
      return `
        <div class="sdk-symbol-wrap ${isKeypad ? 'is-pad-symbol' : 'is-cell-symbol'}">
          <img src="${item.src}" alt="${item.alt}" class="sdk-3d-img" draggable="false" loading="eager" />
          ${isKeypad ? `<span class="sdk-pad-label">${item.name}</span>` : ''}
        </div>
      `;
    }
    if (item.type === 'num') {
      return `
        <div class="sdk-symbol-wrap ${isKeypad ? 'is-pad-num-wrap' : 'is-cell-num-wrap'}">
          <div class="sdk-num-badge ${item.cls}">
            <span class="sdk-num-text">${item.num}</span>
          </div>
          ${isKeypad ? `<span class="sdk-pad-label">${item.name}</span>` : ''}
        </div>
      `;
    }
    return `<span class="sdk-raw-sym">${val}</span>`;
  }

  function generateSudokuBoard(mode) {
    const s = ArcadeHub.sudoku;
    s.mode = mode;
    if (mode === 'fruit4') {
      s.size = 4; s.boxR = 2; s.boxC = 2;
      s.symbols = ['🍎', '🍌', '🍓', '🍇'];
    } else if (mode === 'shape4') {
      s.size = 4; s.boxR = 2; s.boxC = 2;
      s.symbols = ['⭐', '💎', '❤️', '🚀'];
    } else if (mode === 'num4') {
      s.size = 4; s.boxR = 2; s.boxC = 2;
      s.symbols = ['1', '2', '3', '4'];
    } else {
      s.size = 6; s.boxR = 2; s.boxC = 3;
      s.symbols = ['1', '2', '3', '4', '5', '6'];
    }

    const N = s.size;
    // Temel geçerli Latin/Sudoku tablosu üret ve sembolleri karıştır
    const perm = Array.from({ length: N }, (_, i) => i).sort(() => Math.random() - 0.5);
    const base = [];
    for (let r = 0; r < N; r++) {
      const row = [];
      const shift = (r * s.boxC + Math.floor(r / s.boxR)) % N;
      for (let c = 0; c < N; c++) {
        const symIdx = perm[(c + shift) % N];
        row.push(s.symbols[symIdx]);
      }
      base.push(row);
    }

    // Aynı blok içindeki satırları karıştır
    for (let br = 0; br < N; br += s.boxR) {
      if (Math.random() < 0.5) {
        const tmp = base[br];
        base[br] = base[br + 1];
        base[br + 1] = tmp;
      }
    }

    s.solution = base.map(r => r.slice());
    s.puzzle = base.map(r => r.slice());
    const blanksPerRow = (N === 4) ? 2 : 3;
    for (let r = 0; r < N; r++) {
      const cols = Array.from({ length: N }, (_, i) => i).sort(() => Math.random() - 0.5);
      for (let k = 0; k < blanksPerRow; k++) {
        s.puzzle[r][cols[k]] = null;
      }
    }

    s.userGrid = s.puzzle.map(r => r.slice());
    s.statusStates = Array.from({ length: N }, () => Array(N).fill(''));
    s.selectedCell = null;
    // İlk boş hücreyi otomatik seç
    for (let r = 0; r < N && !s.selectedCell; r++) {
      for (let c = 0; c < N; c++) {
        if (s.puzzle[r][c] === null) {
          s.selectedCell = { r, c };
          break;
        }
      }
    }
  }

  function initArcadeSudokuGame() {
    const iconEl = document.getElementById('arcadeStageIcon');
    const titleEl = document.getElementById('arcadeStageTitle');
    const toolbarEl = document.getElementById('arcadeStageToolbar');
    if (iconEl) iconEl.textContent = '🧩';
    if (titleEl) titleEl.textContent = 'Çocuk Sudokusu: Mantık ve Zeka Atölyesi';

    const s = ArcadeHub.sudoku;
    generateSudokuBoard(s.mode || 'fruit4');

    if (toolbarEl) {
      toolbarEl.innerHTML = `
        <div class="arc-toolbar-group">
          <button class="arc-pill-btn ${s.mode === 'fruit4' ? 'active' : ''}" data-sdk-mode="fruit4" type="button">🍎 4x4 Meyve</button>
          <button class="arc-pill-btn ${s.mode === 'shape4' ? 'active' : ''}" data-sdk-mode="shape4" type="button">⭐ 4x4 Şekil & Uzay</button>
          <button class="arc-pill-btn ${s.mode === 'num4' ? 'active' : ''}" data-sdk-mode="num4" type="button">🔢 4x4 Rakam</button>
          <button class="arc-pill-btn ${s.mode === 'num6' ? 'active' : ''}" data-sdk-mode="num6" type="button">🧠 6x6 Rakam</button>
        </div>
      `;
      toolbarEl.querySelectorAll('[data-sdk-mode]').forEach(btn => {
        addTapListener(btn, () => {
          ArcadeHub.sudoku.mode = btn.getAttribute('data-sdk-mode');
          audio.playClick();
          initArcadeSudokuGame();
        });
      });
    }

    renderArcadeSudokuStage();
  }

  function renderArcadeSudokuStage(bannerMsg = '') {
    const canvas = document.getElementById('arcadeStageCanvas');
    if (!canvas) return;
    const s = ArcadeHub.sudoku;
    const N = s.size;

    const selVal = (s.selectedCell && s.userGrid[s.selectedCell.r] && s.userGrid[s.selectedCell.r][s.selectedCell.c]) 
      ? s.userGrid[s.selectedCell.r][s.selectedCell.c] 
      : null;

    let emptyCount = 0;
    for (let r = 0; r < N; r++) {
      for (let c = 0; c < N; c++) {
        if (s.puzzle[r][c] === null && !s.userGrid[r][c]) {
          emptyCount++;
        }
      }
    }

    let gridHtml = '';
    for (let r = 0; r < N; r++) {
      for (let c = 0; c < N; c++) {
        const isFixed = s.puzzle[r][c] !== null;
        const val = s.userGrid[r][c] || '';
        const isSel = s.selectedCell && s.selectedCell.r === r && s.selectedCell.c === c;
        const st = s.statusStates[r][c];

        // Aktif hücrenin bulunduğu satır, sütun veya alt kutu yumuşak arka plan aydınlatması
        let inAxis = false;
        if (s.selectedCell) {
          const sameRow = (s.selectedCell.r === r);
          const sameCol = (s.selectedCell.c === c);
          const sameBox = (Math.floor(r / s.boxR) === Math.floor(s.selectedCell.r / s.boxR) && Math.floor(c / s.boxC) === Math.floor(s.selectedCell.c / s.boxC));
          if (sameRow || sameCol || sameBox) inAxis = true;
        }

        // Tahtadaki aynı simgeyi taşıyan diğer kutuları vurgulama (öğrencinin takip edebilmesi için)
        const isSameVal = Boolean(selVal && val && val === selVal);

        // Kutu bölme kalın çizgileri (4x4'te 2x2, 6x6'da 2x3 kutular)
        const borderRight = ((c + 1) % s.boxC === 0 && c < N - 1) ? 'sdk-box-right' : '';
        const borderBottom = ((r + 1) % s.boxR === 0 && r < N - 1) ? 'sdk-box-bottom' : '';

        // Dama tahtası şeklinde kutu tonlaması
        const boxRIdx = Math.floor(r / s.boxR);
        const boxCIdx = Math.floor(c / s.boxC);
        const boxTint = ((boxRIdx + boxCIdx) % 2 === 0) ? 'sdk-box-tint-a' : 'sdk-box-tint-b';

        const isLastPlaced = s.lastPlaced && s.lastPlaced.r === r && s.lastPlaced.c === c && (Date.now() - s.lastPlaced.time < 1300);
        const animClass = isLastPlaced ? (s.lastPlaced.hasConflict ? 'cell-shake' : 'cell-pop-in') : '';

        gridHtml += `
          <button class="sdk-cell ${isFixed ? 'is-fixed' : 'is-editable'} ${isSel ? 'is-selected' : ''} ${inAxis ? 'in-active-axis' : ''} ${isSameVal ? 'is-same-symbol' : ''} ${st ? 'cell-' + st : ''} ${animClass} ${borderRight} ${borderBottom} ${boxTint}"
                  data-sdk-r="${r}" data-sdk-c="${c}" type="button" aria-label="${val ? val : 'Boş Kutu'}">
            ${isFixed ? '<span class="sdk-fixed-badge" title="Sabit İpucu">🔒</span>' : ''}
            ${renderSudokuSymbolHtml(val)}
          </button>
        `;
      }
    }

    canvas.innerHTML = `
      <div class="arc-sudoku-arena">
        <!-- Üst Kural ve Durum Çubuğu -->
        <div class="sdk-header-panel">
          <div class="sdk-instructions-pill">
            <span class="sdk-inst-icon">💡</span>
            <span class="sdk-inst-text"><strong>Sudoku Kuralı:</strong> Her satır, sütun ve kalın kutuda her simge <strong>yalnızca 1 kez</strong> bulunabilir!</span>
          </div>
          <div class="sdk-progress-badge" title="Doldurulması gereken boş kutu sayısı">
            <span>🎯 Kalan Boş: <strong>${emptyCount}</strong></span>
          </div>
        </div>

        ${bannerMsg ? `<div class="sdk-feedback-banner ${bannerMsg.includes('TEBRİKLER') ? 'banner-win' : (bannerMsg.includes('hata') ? 'banner-err' : 'banner-info')}">${bannerMsg}</div>` : ''}

        <div class="sdk-main-layout">
          <!-- Sol / Üst: Şık 3D Ahşap/Oyun Kartı Sudoku Tahtası -->
          <div class="sdk-board-wrapper">
            <div class="sdk-board grid-${N}x${N}">
              ${gridHtml}
            </div>
          </div>

          <!-- Sağ / Alt: Etkileşimli Tuş Takımı ve Aksiyonlar -->
          <div class="sdk-side-controls">
            <div class="sdk-pad-header">
              <span class="sdk-pad-icon">👇</span>
              <span class="sdk-pad-title">Seçili Kutuya Yerleştir:</span>
            </div>
            <div class="sdk-symbol-pad sdk-pad-grid-${N}">
              ${s.symbols.map(sym => `
                <button class="sdk-pad-btn" data-sdk-sym="${sym}" type="button" title="${sym}">
                  ${renderSudokuSymbolHtml(sym, true)}
                </button>
              `).join('')}
              <button class="sdk-pad-btn sdk-btn-erase" id="btnSdkErase" type="button" title="Seçili kutuyu temizle">
                <div class="sdk-symbol-wrap is-pad-symbol">
                  <span class="sdk-erase-icon">🧹</span>
                  <span class="sdk-pad-label">Sil</span>
                </div>
              </button>
            </div>

            <div class="sdk-action-buttons">
              <button class="sdk-action-btn sdk-btn-check" id="btnSdkCheck" type="button">
                <span class="btn-icon">✅</span>
                <span class="btn-text">Kontrol Et</span>
              </button>
              <div class="sdk-action-subgroup">
                <button class="sdk-action-btn sdk-btn-hint" id="btnSdkHint" type="button">
                  <span class="btn-icon">💡</span>
                  <span class="btn-text">İpucu Ver</span>
                </button>
                <button class="sdk-action-btn sdk-btn-new" id="btnSdkNew" type="button">
                  <span class="btn-icon">🔄</span>
                  <span class="btn-text">Yeni Bulmaca</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    `;

    canvas.querySelectorAll('[data-sdk-r]').forEach(cell => {
      addTapListener(cell, () => {
        const r = parseInt(cell.getAttribute('data-sdk-r'), 10);
        const c = parseInt(cell.getAttribute('data-sdk-c'), 10);
        s.selectedCell = { r, c };
        audio.playClick();
        renderArcadeSudokuStage();
      });
    });

    canvas.querySelectorAll('[data-sdk-sym]').forEach(btn => {
      addTapListener(btn, () => {
        const sym = btn.getAttribute('data-sdk-sym');
        if (!s.selectedCell) {
          showToast('Lütfen önce yerleştirmek istediğin kutuyu seç!');
          return;
        }
        const { r, c } = s.selectedCell;
        if (s.puzzle[r][c] !== null) {
          showToast('🔒 Bu kutu oyunun başında verilen sabit ipucudur, değiştirilemez.');
          audio.playWrong();
          return;
        }
        const hasConflict = isSudokuCellConflict(s.userGrid, N, s.boxR, s.boxC, r, c, sym);
        s.userGrid[r][c] = sym;
        s.lastPlaced = { r, c, hasConflict, time: Date.now() };

        if (hasConflict) {
          audio.playWrong();
          s.statusStates[r][c] = 'wrong';
        } else {
          audio.playPop();
          s.statusStates[r][c] = '';
        }
        renderArcadeSudokuStage();
        // Otomatik tamamlama kontrolü
        checkSudokuIfFull();
      });
    });

    const btnErase = document.getElementById('btnSdkErase');
    if (btnErase) {
      addTapListener(btnErase, () => {
        if (!s.selectedCell) {
          showToast('Lütfen önce temizlemek istediğin kutuyu seç!');
          return;
        }
        const { r, c } = s.selectedCell;
        if (s.puzzle[r][c] !== null) {
          showToast('🔒 Bu kutu oyunun başında verilen sabit ipucudur, silinemez.');
          audio.playWrong();
          return;
        }
        s.userGrid[r][c] = null;
        s.statusStates[r][c] = '';
        audio.playClick();
        renderArcadeSudokuStage();
      });
    }

    const btnCheck = document.getElementById('btnSdkCheck');
    if (btnCheck) addTapListener(btnCheck, validateSudokuBoard);

    const btnHint = document.getElementById('btnSdkHint');
    if (btnHint) addTapListener(btnHint, giveSudokuHint);

    const btnNew = document.getElementById('btnSdkNew');
    if (btnNew) addTapListener(btnNew, () => {
      audio.playClick();
      generateSudokuBoard(s.mode);
      renderArcadeSudokuStage();
    });
  }

    function isSudokuCellConflict(grid, N, boxR, boxC, r, c, val) {
    if (!val) return false;
    for (let k = 0; k < N; k++) {
      if (k !== c && grid[r][k] === val) return true;
      if (k !== r && grid[k][c] === val) return true;
    }
    const startR = Math.floor(r / boxR) * boxR;
    const startC = Math.floor(c / boxC) * boxC;
    for (let rr = startR; rr < startR + boxR; rr++) {
      for (let cc = startC; cc < startC + boxC; cc++) {
        if ((rr !== r || cc !== c) && grid[rr][cc] === val) return true;
      }
    }
    return false;
  }

  function checkSudokuIfFull() {
    const s = ArcadeHub.sudoku;
    const N = s.size;
    for (let r = 0; r < N; r++) {
      for (let c = 0; c < N; c++) {
        if (!s.userGrid[r][c]) {
          renderArcadeSudokuStage();
          return;
        }
      }
    }
    validateSudokuBoard();
  }

  function validateSudokuBoard() {
    const s = ArcadeHub.sudoku;
    const N = s.size;
    let emptyCount = 0;
    let wrongCount = 0;

    for (let r = 0; r < N; r++) {
      for (let c = 0; c < N; c++) {
        if (s.puzzle[r][c] !== null) {
          s.statusStates[r][c] = '';
          continue;
        }
        const val = s.userGrid[r][c];
        if (!val) {
          emptyCount += 1;
          s.statusStates[r][c] = '';
        } else if (val === s.solution[r][c] && !isSudokuCellConflict(s.userGrid, N, s.boxR, s.boxC, r, c, val)) {
          s.statusStates[r][c] = 'correct';
        } else {
          wrongCount += 1;
          s.statusStates[r][c] = 'wrong';
        }
      }
    }

    if (wrongCount === 0 && emptyCount === 0) {
      audio.playFanfare();
      if (typeof launchConfetti === 'function') launchConfetti();
      if (!state.isMuted && state.soundEnabled) {
        audio.speakTurkishText('Harikasın! Sudoku bulmacasını hatasız tamamladın!');
      }
      renderArcadeSudokuStage('🎉 TEBRİKLER! Sudoku Bulmacasını Hatasız Tamamladın! 🏆');
      showArcadeVictoryModal({
        title: 'MÜKEMMEL ZEKA! 🧩',
        subtitle: 'Sudoku bulmacasını hiç hata yapmadan eksiksiz tamamladın!',
        badgeText: 'SUDOKU USTASI',
        icon: '🧩',
        onRestart: () => {
          generateSudokuBoard(s.mode);
          renderArcadeSudokuStage();
        }
      });
    } else if (wrongCount > 0) {
      audio.playWrong();
      renderArcadeSudokuStage(`⚠️ ${wrongCount} kutuda hata var (Kırmızı kutuları kontrol et).`);
    } else {
      audio.playCorrect();
      renderArcadeSudokuStage(`👍 Şimdiye kadar hepsi doğru! Kalan boş kutu: ${emptyCount}`);
    }
  }

  function giveSudokuHint() {
    const s = ArcadeHub.sudoku;
    const N = s.size;
    let target = s.selectedCell;
    if (!target || s.puzzle[target.r][target.c] !== null || s.userGrid[target.r][target.c] === s.solution[target.r][target.c]) {
      target = null;
      for (let r = 0; r < N && !target; r++) {
        for (let c = 0; c < N; c++) {
          if (s.puzzle[r][c] === null && s.userGrid[r][c] !== s.solution[r][c]) {
            target = { r, c };
            break;
          }
        }
      }
    }
    if (!target) {
      showToast('✨ Tüm kutular zaten doğru dolu!');
      return;
    }
    s.selectedCell = target;
    s.userGrid[target.r][target.c] = s.solution[target.r][target.c];
    s.statusStates[target.r][target.c] = 'correct';
    audio.playCorrect();
    checkSudokuIfFull();
  }

  // =========================================================================
  // OYUN 3: ❌⭕ AKILLI XOX (KLASİK & SONSUZ 3 TAŞ MODU)
  // =========================================================================
  const XOX_WIN_LINES = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6]
  ];

  function initArcadeXoxGame(keepScores = false) {
    const iconEl = document.getElementById('arcadeStageIcon');
    const titleEl = document.getElementById('arcadeStageTitle');
    const toolbarEl = document.getElementById('arcadeStageToolbar');
    if (iconEl) iconEl.textContent = '❌⭕';
    if (titleEl) titleEl.textContent = 'Akıllı XOX: Klasik & Sonsuz 3 Taş Modu';

    const x = ArcadeHub.xox;
    x.board = Array(9).fill(null);
    x.movesX = [];
    x.movesO = [];
    x.turn = 'X';
    x.winner = null;
    x.winLine = [];
    x.aiThinking = false;
    if (!keepScores) {
      x.scoreX = 0;
      x.scoreO = 0;
    }

    if (toolbarEl) {
      toolbarEl.innerHTML = `
        <div class="arc-toolbar-group">
          <button class="arc-pill-btn ${!x.vsAi ? 'active' : ''}" id="btnXox2P" type="button">👥 2 Kişilik (Arkadaşınla)</button>
          <button class="arc-pill-btn ${x.vsAi ? 'active' : ''}" id="btnXoxAi" type="button">🤖 Moli'ye Karşı (Yapay Zeka)</button>
          <button class="arc-pill-btn ${x.infiniteMode ? 'active pill-fire' : ''}" id="btnXoxInfinite" type="button">
            🔥 Sonsuz 3 Taş Modu: ${x.infiniteMode ? 'AÇIK' : 'KAPALI'}
          </button>
          <button class="arc-pill-btn arc-btn-restart" id="btnXoxReset" type="button">🔄 Yeni Tur</button>
        </div>
      `;
      const b2p = document.getElementById('btnXox2P');
      const bAi = document.getElementById('btnXoxAi');
      const bInf = document.getElementById('btnXoxInfinite');
      const bRes = document.getElementById('btnXoxReset');

      if (b2p) addTapListener(b2p, () => { x.vsAi = false; audio.playClick(); initArcadeXoxGame(false); });
      if (bAi) addTapListener(bAi, () => { x.vsAi = true; audio.playClick(); initArcadeXoxGame(false); });
      if (bInf) addTapListener(bInf, () => { x.infiniteMode = !x.infiniteMode; audio.playClick(); initArcadeXoxGame(true); });
      if (bRes) addTapListener(bRes, () => { audio.playClick(); initArcadeXoxGame(true); });
    }

    renderArcadeXoxStage();
  }

  function checkXoxWinner(board) {
    for (const line of XOX_WIN_LINES) {
      const [a, b, c] = line;
      if (board[a] && board[a] === board[b] && board[a] === board[c]) {
        return { winner: board[a], line };
      }
    }
    if (board.every(cell => cell !== null)) {
      return { winner: 'draw', line: [] };
    }
    return null;
  }

  function renderXoxPieceHtml(val) {
    if (!val) return '';
    if (val === 'X') {
      return `
        <div class="xox-stone stone-x">
          <svg viewBox="0 0 72 72" class="xox-svg-glyph" aria-hidden="true">
            <defs>
              <filter id="xGlow" x="-30%" y="-30%" width="160%" height="160%">
                <feDropShadow dx="0" dy="3" stdDeviation="4" flood-color="#0284C7" flood-opacity="0.55"/>
              </filter>
              <linearGradient id="xGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="#38BDF8"/>
                <stop offset="100%" stop-color="#0284C7"/>
              </linearGradient>
            </defs>
            <line x1="18" y1="18" x2="54" y2="54" stroke="url(#xGrad)" stroke-width="12" stroke-linecap="round" filter="url(#xGlow)"/>
            <line x1="54" y1="18" x2="18" y2="54" stroke="url(#xGrad)" stroke-width="12" stroke-linecap="round" filter="url(#xGlow)"/>
            <circle cx="36" cy="36" r="4.5" fill="#E0F2FE"/>
          </svg>
        </div>
      `;
    }
    if (val === 'O') {
      return `
        <div class="xox-stone stone-o">
          <svg viewBox="0 0 72 72" class="xox-svg-glyph" aria-hidden="true">
            <defs>
              <filter id="oGlow" x="-30%" y="-30%" width="160%" height="160%">
                <feDropShadow dx="0" dy="3" stdDeviation="4" flood-color="#EA580C" flood-opacity="0.55"/>
              </filter>
              <linearGradient id="oGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="#FB923C"/>
                <stop offset="100%" stop-color="#EA580C"/>
              </linearGradient>
            </defs>
            <circle cx="36" cy="36" r="23" stroke="url(#oGrad)" stroke-width="11" fill="none" stroke-linecap="round" filter="url(#oGlow)"/>
            <circle cx="36" cy="36" r="14" stroke="#FFEDD5" stroke-width="2.5" fill="none" opacity="0.6"/>
          </svg>
        </div>
      `;
    }
    return '';
  }

  function renderArcadeXoxStage() {
    const canvas = document.getElementById('arcadeStageCanvas');
    if (!canvas) return;
    const x = ArcadeHub.xox;

    // Sonsuz modda 3 taşı olan oyuncuların en eski taşları
    const oldestX = (x.movesX.length === 3 && !x.winner) ? x.movesX[0] : -1;
    const oldestO = (x.movesO.length === 3 && !x.winner) ? x.movesO[0] : -1;

    let statusText = '';
    if (x.winner === 'X') {
      statusText = '🏆 ❌ 1. OYUNCU KAZANDI! 🎉';
    } else if (x.winner === 'O') {
      statusText = x.vsAi ? '🤖 MOLI KAZANDI! Tekrar dene! 🎉' : '🏆 ⭕ 2. OYUNCU KAZANDI! 🎉';
    } else if (x.winner === 'draw') {
      statusText = '🤝 BERABERE! Yeni tura başlayın.';
    } else {
      statusText = x.turn === 'X'
        ? '👉 Sıra: ❌ 1. Oyuncu'
        : (x.vsAi ? '🤖 Moli hamlesini düşünüyor...' : '👉 Sıra: ⭕ 2. Oyuncu');
    }

    canvas.innerHTML = `
      <div class="arc-xox-arena">
        <div class="xox-scoreboard">
          <div class="xox-player-pill pill-x ${x.turn === 'X' && !x.winner ? 'active-turn' : ''}">
            <span>❌ 1. Oyuncu</span>
            <strong>${x.scoreX}</strong>
          </div>
          <div class="xox-status-banner">${statusText}</div>
          <div class="xox-player-pill pill-o ${x.turn === 'O' && !x.winner ? 'active-turn' : ''}">
            <span>${x.vsAi ? '🤖 Moli (⭕)' : '⭕ 2. Oyuncu'}</span>
            <strong>${x.scoreO}</strong>
          </div>
        </div>

        ${x.infiniteMode ? `
          <div class="xox-infinite-hint">
            🔥 <strong>Sonsuz 3 Taş Kuralı:</strong> Her oyuncunun tahtada en fazla 3 taşı olabilir. 4. taş koyulduğunda <strong>⏳ yanıp sönen ilk taş</strong> otomatik silinir!
          </div>
        ` : ''}

        <div class="xox-board-grid ${x.winner ? 'is-game-over' : ''}">
          ${x.board.map((val, idx) => {
            const isWin = x.winLine.includes(idx);
            const isOldestX = (x.infiniteMode && idx === oldestX);
            const isOldestO = (x.infiniteMode && idx === oldestO);
            const isFadingActive = (isOldestX && x.turn === 'X') || (isOldestO && x.turn === 'O');
            const isFadingHint = (isOldestX && x.turn !== 'X') || (isOldestO && x.turn !== 'O');

            return `
              <button class="xox-cell ${val ? 'cell-' + val.toLowerCase() : ''} ${isWin ? 'is-win-cell' : ''} ${isFadingActive ? 'is-fading-piece is-active-fading' : ''} ${isFadingHint ? 'is-fading-hint' : ''}"
                      data-xox-idx="${idx}" type="button" ${val || x.winner || x.aiThinking ? 'disabled' : ''} aria-label="${val ? val : 'Boş Kutu'}">
                <div class="xox-cell-content">
                  ${renderXoxPieceHtml(val)}
                </div>
                ${isFadingActive ? '<div class="fading-badge is-active"><span class="badge-icon">⏳</span><span>Silinecek</span></div>' : (isFadingHint ? '<div class="fading-badge is-hint"><span class="badge-icon">⏳</span><span>1. Taş</span></div>' : '')}
              </button>
            `;
          }).join('')}
        </div>

        ${x.winner ? `
          <div class="xox-rematch-row">
            <button class="tt-ctrl-btn tt-btn-start" id="btnXoxPlayAgain" type="button">🔄 Tekrar Oyna</button>
          </div>
        ` : ''}
      </div>
    `;

    canvas.querySelectorAll('[data-xox-idx]').forEach(btn => {
      addTapListener(btn, () => {
        const idx = parseInt(btn.getAttribute('data-xox-idx'), 10);
        handleXoxMove(idx);
      });
    });

    const btnAgain = document.getElementById('btnXoxPlayAgain');
    if (btnAgain) addTapListener(btnAgain, () => { audio.playClick(); initArcadeXoxGame(true); });
  }

  function handleXoxMove(idx) {
    const x = ArcadeHub.xox;
    if (x.winner || x.board[idx] !== null || x.aiThinking) return;

    placeXoxPiece(idx, x.turn);
    if (!x.winner && x.vsAi && x.turn === 'O') {
      x.aiThinking = true;
      renderArcadeXoxStage();
      setTimeout(() => {
        x.aiThinking = false;
        const aiIdx = computeMoliXoxMove();
        if (aiIdx !== -1) {
          placeXoxPiece(aiIdx, 'O');
        }
      }, 450);
    }
  }

  function placeXoxPiece(idx, symbol) {
    const x = ArcadeHub.xox;
    if (x.winner) return;

    const queue = symbol === 'X' ? x.movesX : x.movesO;

    if (x.infiniteMode && queue.length >= 3) {
      const oldestIdx = queue.shift();
      x.board[oldestIdx] = null;
    }
    x.board[idx] = symbol;
    queue.push(idx);
    audio.playPop();

    const res = checkXoxWinner(x.board);
    if (res) {
      // 1) KAZANMA DURUMUNDA OYUNU ANINDA DURDUR (Tahtayı anında kilitle)
      x.winner = res.winner;
      x.winLine = res.line;
      x.aiThinking = false;
      renderArcadeXoxStage();

      // 2) KAZANAN EKRANI (MODAL) VE GÖRSEL ŞÖLEN (Konfeti + Alkış/Zafer Sesi)
      if (res.winner === 'X') {
        x.scoreX += 1;
        audio.playFanfare();
        if (typeof launchConfetti === 'function') {
          launchConfetti();
          setTimeout(launchConfetti, 380);
        }
        setTimeout(() => {
          showArcadeVictoryModal({
            title: "🎉 TEBRİKLER! 'X' KAZANDI!",
            subtitle: "Mükemmel bir hamle taktiğiyle 3'lü sırayı tamamladın!",
            badgeText: 'XOX ŞAMPİYONU',
            icon: '❌',
            onRestart: () => initArcadeXoxGame(true)
          });
        }, 280);
      } else if (res.winner === 'O') {
        x.scoreO += 1;
        audio.playFanfare();
        if (typeof launchConfetti === 'function') {
          launchConfetti();
          setTimeout(launchConfetti, 380);
        }
        const oTitle = x.vsAi ? "🎉 TEBRİKLER! 'O' (MOLİ) KAZANDI!" : "🎉 TEBRİKLER! 'O' KAZANDI!";
        const oSub = x.vsAi
          ? "Moli bu turda zekice hamlelerle kazandı! Rövanş için hemen tekrar dene!"
          : "Mükemmel bir hamle taktiğiyle 3'lü sırayı tamamladın!";
        setTimeout(() => {
          showArcadeVictoryModal({
            title: oTitle,
            subtitle: oSub,
            badgeText: x.vsAi ? 'MOLİ GALİP' : 'XOX ŞAMPİYONU',
            icon: '⭕',
            onRestart: () => initArcadeXoxGame(true)
          });
        }, 280);
      } else if (res.winner === 'draw') {
        audio.playVictory();
        setTimeout(() => {
          showArcadeVictoryModal({
            title: '🤝 OYUN BERABERE!',
            subtitle: 'Her iki taraf da harika oynadı, tahtada beraberlik sağlandı!',
            badgeText: 'DOSTLUK KAZANDI',
            icon: '🤝',
            onRestart: () => initArcadeXoxGame(true)
          });
        }, 280);
      }
    } else {
      x.turn = (symbol === 'X') ? 'O' : 'X';
      renderArcadeXoxStage();
    }
  }

  function computeMoliXoxMove() {
    const x = ArcadeHub.xox;
    const empty = [];
    for (let i = 0; i < 9; i++) {
      if (x.board[i] === null) empty.push(i);
    }
    if (empty.length === 0) return -1;

    // 1) Moli kazanabiliyor mu?
    for (const cand of empty) {
      const sim = x.board.slice();
      if (x.infiniteMode && x.movesO.length >= 3) sim[x.movesO[0]] = null;
      sim[cand] = 'O';
      const w = checkXoxWinner(sim);
      if (w && w.winner === 'O') return cand;
    }

    // 2) Rakip (X) bir sonraki hamlede kazanabiliyor mu? Engelle!
    for (const cand of empty) {
      const sim = x.board.slice();
      if (x.infiniteMode && x.movesX.length >= 3) sim[x.movesX[0]] = null;
      sim[cand] = 'X';
      const w = checkXoxWinner(sim);
      if (w && w.winner === 'X') return cand;
    }

    // 3) Merkez boşsa merkezi al
    if (empty.includes(4)) return 4;

    // 4) Köşelerden birini seç
    const corners = [0, 2, 6, 8].filter(c => empty.includes(c));
    if (corners.length > 0) return corners[Math.floor(Math.random() * corners.length)];

    return empty[Math.floor(Math.random() * empty.length)];
  }

